pub const Spec = struct { mask: u16, label: []const u8 };
pub const candidates = [_]Spec{
    .{ .mask = 0x001f, .label = "leading0" },
    .{ .mask = 0x0307, .label = "lowbytes" },
    .{ .mask = 0x800f, .label = "wrap15" },
    .{ .mask = 0x0703, .label = "mirror_low" },
};

