    var sorted_b: [max_pairs]u64 = undefined;
    @memcpy(sorted_a[0..opts.pairs], baseline[0..opts.pairs]);
    @memcpy(sorted_b[0..opts.pairs], candidate[0..opts.pairs]);
    std.mem.sort(u64, sorted_a[0..opts.pairs], {}, std.sort.asc(u64));
    std.mem.sort(u64, sorted_b[0..opts.pairs], {}, std.sort.asc(u64));
    std.mem.sort(f64, ratios[0..opts.pairs], {}, std.sort.asc(f64));
    const index = opts.pairs / 2;
    std.debug.print("{{\"type\":\"result\",\"id\":{d},\"label\":\"{s}\",\"mask\":{d},\"direction\":\"{s}\",\"seed\":{d},\"pairs\":{d},\"calls\":{d},\"baseline_ns\":{d:.6},\"candidate_ns\":{d:.6},\"median_paired_ratio\":{d:.9},\"checksum\":\"{x}\",\"baseline_elapsed_ns\":[", .{ id, spec.label, spec.mask, if (inverse) "decrypt" else "encrypt", opts.seed, opts.pairs, opts.calls, @as(f64, @floatFromInt(sorted_a[index])) / @as(f64, @floatFromInt(opts.calls)), @as(f64, @floatFromInt(sorted_b[index])) / @as(f64, @floatFromInt(opts.calls)), ratios[index], @as(u128, @bitCast(output)) });
    for (baseline[0..opts.pairs], 0..) |ns, i| std.debug.print("{s}{d}", .{ if (i == 0) "" else ",", ns });
    std.debug.print("],\"candidate_elapsed_ns\":[", .{});
    for (candidate[0..opts.pairs], 0..) |ns, i| std.debug.print("{s}{d}", .{ if (i == 0) "" else ",", ns });
    std.debug.print("]}}\n", .{});
}

pub fn main(comptime first: usize, comptime end: usize) !void {
    const opts = try parseOptions();
    if (opts.candidate) |id| if (id != 0 and (id < first or id >= end)) return error.CandidateNotInThisBatch;
    std.debug.print("{{\"type\":\"config\",\"inline_policy\":\"always_inline\",\"first\":{d},\"end\":{d},\"zig\":\"{s}\",\"cpu\":\"{s}\",\"backend\":\"{s}\",\"seed\":{d},\"pairs\":{d},\"calls\":{d}}}\n", .{ first, end, builtin.zig_version_string, builtin.cpu.model.name, @tagName(builtin.zig_backend), opts.seed, opts.pairs, opts.calls });
    try validate(first, end, opts);
    var prng = std.Random.DefaultPrng.init(opts.seed ^ 0x62656e63686d6172);
    const random = prng.random();
    var key: [32]u8 = undefined;
    random.bytes(&key);
    const cipher = kuz.Cipher.init(key);
    var initial: B = undefined;
    random.bytes(std.mem.asBytes(&initial));
    inline for (list.candidates, 0..) |spec, id| {
        if (comptime id == 0 or (id >= first and id < end)) {
            if (opts.candidate == null or opts.candidate.? == id) {
                try compare(id, spec, false, &cipher, initial, opts);
                try compare(id, spec, true, &cipher, initial, opts);
            }
        }
    }
